exercises.solution:
#include <string>
#include <vector>
#include <cmath>

struct Target
{
    std::string name;
    double x;
    double y;
};

class Turret
{
public:
    Turret(double x, double y, double range) : x(x), y(y), range(range) {}
    double distanceTo(const Target& t) const
    {
        double dx = t.x - x, dy = t.y - y;
        return std::sqrt(dx * dx + dy * dy);
    }
    bool inRange(const Target& t) const { return distanceTo(t) <= range; }
    int pickTarget(const std::vector<Target>& targets) const
    {
        int best = -1;
        double bestDist = 0;
        for (int i = 0; i < (int)targets.size(); i++) {
            double d = distanceTo(targets[i]);
            if (d <= range && (best == -1 || d < bestDist)) { best = i; bestDist = d; }
        }
        return best;
    }
private:
    double x, y, range;
};

