exercises.solution:
class Gun
{
public:
    Gun(double shotsPerSecond) : cooldown(1.0 / shotsPerSecond) {}
    bool tryFire(double now)
    {
        if (!fired || now - lastShot >= cooldown) {
            fired = true;
            lastShot = now;
            return true;
        }
        return false;
    }
private:
    double cooldown;
    double lastShot = 0;
    bool fired = false;
};
